import{_ as a,o as i,c as t,a3 as o}from"./chunks/framework.Dz5Q8p4s.js";const p=JSON.parse('{"title":"Video Generation for Embodied AI","description":"","frontmatter":{"title":"Video Generation for Embodied AI","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/video-for-embodied-ai.md","filePath":"en/tutorials/video-for-embodied-ai.md","lastUpdated":null}'),r={name:"en/tutorials/video-for-embodied-ai.md"};function l(n,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="video-generation-for-embodied-ai" tabindex="-1">Video Generation for Embodied AI <a class="header-anchor" href="#video-generation-for-embodied-ai" aria-label="Permalink to &quot;Video Generation for Embodied AI&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a><strong>Coverage</strong>: June 2025 – July 2026, with 2023 – mid-2025 foundations included so the tutorial is self-contained. <strong>Papers</strong>: <a href="/notes/en/papers/#tut-video-for-embodied-ai">40 deep-read notes</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/video-for-embodied-ai">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>Video generation can serve robotics in <strong>five distinct roles</strong>, and the tutorial&#39;s contribution is refusing to blur them: (1) generation as planning or policy, (2) prediction as representation, (3) world model / simulator / evaluator, (4) data engine, and (5) unified VLA plus world model. A paper that is excellent in role 4 may be worthless in role 1, and most confusion in the literature comes from comparing systems across roles.</p><p>Running through every chapter is what the tutorial calls the soul question: <strong>do you actually have to generate pixels?</strong> Chapter 7.1 makes the case on both sides — pixels give a general, pretrainable interface and a human-inspectable artefact, but they cost latency, and much of the information they carry is irrelevant to control. Chapter 6 answers the companion question of evaluation with a five-level ladder that ends at closed-loop task success, and adds a fifth level for the credibility of world models used as evaluators.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-how-to-use-this-tutorial" tabindex="-1">Chapter 0 — How to use this tutorial <a class="header-anchor" href="#chapter-0-—-how-to-use-this-tutorial" aria-label="Permalink to &quot;Chapter 0 — How to use this tutorial&quot;">​</a></h3><ul><li>0.1 The tutorial in one sentence</li><li>0.2 Why this deserved a separate volume</li><li>0.3 Suggested reading paths</li><li>0.4 Scope</li></ul><h3 id="chapter-1-—-why-video-generation-can-serve-embodied-intelligence" tabindex="-1">Chapter 1 — Why video generation can serve embodied intelligence <a class="header-anchor" href="#chapter-1-—-why-video-generation-can-serve-embodied-intelligence" aria-label="Permalink to &quot;Chapter 1 — Why video generation can serve embodied intelligence&quot;">​</a></h3><ul><li>1.1 Pinning down the two terms</li><li>1.2 Why video, rather than some other representation</li><li>1.3 The five roles video generation plays for embodied AI</li><li>1.4 Relation to classical robot learning</li><li>1.5 The soul question that runs through the tutorial</li><li>1.6 What makes such a system good</li></ul><h3 id="chapter-2-—-mathematical-principles-and-key-techniques" tabindex="-1">Chapter 2 — Mathematical principles and key techniques <a class="header-anchor" href="#chapter-2-—-mathematical-principles-and-key-techniques" aria-label="Permalink to &quot;Chapter 2 — Mathematical principles and key techniques&quot;">​</a></h3><ul><li>2.1 Restating decision-making as conditional video generation</li><li>2.2 Three generative paradigms as backbone choices</li><li>2.3 Conditioning signals: how the goal is specified</li><li>2.4 Extracting actions from video: four paradigms</li><li>2.5 Action injection: how robot actions are fed into a video model</li><li>2.6 Latent action learning — the bridge to unlabelled video at scale</li><li>2.7 Turning a video model into a world model / simulator</li><li>2.8 Key techniques for the data-engine role</li><li>2.9 Principles of unified VLA + world model</li><li>2.10 Efficiency and real time: the hard constraint of closed-loop control</li></ul><h3 id="chapter-3-—-task-taxonomy" tabindex="-1">Chapter 3 — Task taxonomy <a class="header-anchor" href="#chapter-3-—-task-taxonomy" aria-label="Permalink to &quot;Chapter 3 — Task taxonomy&quot;">​</a></h3><ul><li>3.1 Tasks organised by purpose</li><li>3.2 Tasks organised by embodiment and scene</li><li>3.3 Task panorama</li></ul><h3 id="chapter-4-—-data" tabindex="-1">Chapter 4 — Data <a class="header-anchor" href="#chapter-4-—-data" aria-label="Permalink to &quot;Chapter 4 — Data&quot;">​</a></h3><ul><li>4.1 Data tiers and the action-label vs diversity trade-off</li><li>4.2 Real-robot datasets: with actions, expensive and precious</li><li>4.3 Human video and cross-morphology data: no actions, enormous scale</li><li>4.4 Simulation platforms and data generators</li><li>4.5 Datasets and benchmarks built specifically for video generation × embodiment</li><li>4.6 The &quot;world model as data engine&quot; paradigm</li></ul><h3 id="chapter-5-—-methods-and-representative-systems" tabindex="-1">Chapter 5 — Methods and representative systems <a class="header-anchor" href="#chapter-5-—-methods-and-representative-systems" aria-label="Permalink to &quot;Chapter 5 — Methods and representative systems&quot;">​</a></h3><ul><li>5.1 Foundational work (2023 – 2025.05) as background</li><li>5.2 Role 1: generation as planning / policy</li><li>5.3 Role 2: prediction as representation</li><li>5.4 Role 3: world model / simulator / evaluator — the WAM explosion</li><li>5.5 Role 4: video generation as data engine</li><li>5.6 Role 5: unified VLA + world model</li><li>5.7 A method panorama compressing all of the above into one map</li></ul><h3 id="chapter-6-—-benchmarks-and-metrics" tabindex="-1">Chapter 6 — Benchmarks and metrics <a class="header-anchor" href="#chapter-6-—-benchmarks-and-metrics" aria-label="Permalink to &quot;Chapter 6 — Benchmarks and metrics&quot;">​</a></h3><ul><li>6.1 Four levels of evaluation, from &quot;looks right&quot; to &quot;is useful&quot;</li><li>6.2 Level 1: video quality metrics — necessary, far from sufficient</li><li>6.3 Level 2: world correctness (action following / physics / consistency)</li><li>6.4 Level 3: embodied utility — is it actually useful to a robot</li><li>6.5 Level 4: closed-loop task success — the ultimate criterion</li><li>6.6 Level 5: the credibility of a world model used as evaluator (meta-evaluation)</li><li>6.7 A quick-reference table for choosing an evaluation</li></ul><h3 id="chapter-7-—-core-challenges-and-research-trends" tabindex="-1">Chapter 7 — Core challenges and research trends <a class="header-anchor" href="#chapter-7-—-core-challenges-and-research-trends" aria-label="Permalink to &quot;Chapter 7 — Core challenges and research trends&quot;">​</a></h3><ul><li>7.1 The soul question: do we need to generate pixels at all</li><li>7.2 Action extraction and action representation</li><li>7.3 Physical plausibility and contact</li><li>7.4 Data: are synthetic pseudo-actions accurate enough</li><li>7.5 Real-time closed loops and latency</li><li>7.6 Long horizons and error accumulation</li><li>7.7 Cross-embodiment and unified large models</li><li>7.8 Evaluator credibility — new and critical</li><li>7.9 A &quot;challenge × representative solution&quot; overview</li></ul><h3 id="chapter-8-—-paper-and-resource-list-2025-06–2026-07" tabindex="-1">Chapter 8 — Paper and resource list (2025.06–2026.07) <a class="header-anchor" href="#chapter-8-—-paper-and-resource-list-2025-06–2026-07" aria-label="Permalink to &quot;Chapter 8 — Paper and resource list (2025.06–2026.07)&quot;">​</a></h3><p>Foundations and background; surveys and position pieces; then one section per role; benchmarks, evaluation and data; adjacent and cross-cutting work including driving WAMs whose methodology transfers; and open-source community lists.</p><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/world-action-models">World-Action Models</a> — role 3 and role 5 in far greater depth</li><li><a href="/notes/en/tutorials/vla">Vision-Language-Action Models</a> — the policy-side counterpart</li><li><a href="/notes/en/tutorials/physics-aware">Physics-Aware Video Generation</a> — where the generated future has to be physically right</li></ul>',27)])])}const m=a(r,[["render",l]]);export{p as __pageData,m as default};
